import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"BlueStore for Ceph Developer Summit - Vampire","description":"","frontmatter":{"title":"BlueStore for Ceph Developer Summit - Vampire","date":"2026-08-14T00:00:00.000Z","updated":"2026-08-15T00:00:00.000Z","tags":["BlueStore","性能优化","存储优化","会议纪要"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/BlueStore_for_Ceph_Developer_Summit_-_Vampire.md","filePath":"posts/2026/BlueStore_for_Ceph_Developer_Summit_-_Vampire.md","lastUpdated":null}'),r={name:"posts/2026/BlueStore_for_Ceph_Developer_Summit_-_Vampire.md"};function i(d,e,s,p,u,c){return t(),l("div",null,[...e[0]||(e[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次 Ceph Developer Summit 专题讨论了 BlueStore 在即将发布的 Lumphier 版本中计划实现的一系列新特性。主讲人 Igor 和 Adam 逐一介绍了八项正在考量的功能，并就 BlueStore 未来演进路径展开了开放讨论。</p><h2 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h2><h3 id="_1-基于-scrub-的空间优化-scrub-based-space-optimization" tabindex="-1">1. 基于 Scrub 的空间优化（Scrub-Based Space Optimization） <a class="header-anchor" href="#_1-基于-scrub-的空间优化-scrub-based-space-optimization" aria-label="Permalink to &quot;1. 基于 Scrub 的空间优化（Scrub-Based Space Optimization）&quot;">​</a></h3><p>该特性目前已进入 review 阶段，是距离合并最近的一项改进。</p><p>核心思路：利用 deep scrubbing 过程中对象已被读入内存的时机，对 BlueStore 对象执行空间优化操作。</p><p>主要动机：BlueStore 长期缺乏碎片整理（defragmentation）能力，随时间推移磁盘空间碎片化可能较为严重。此前采用 allocator 以 round-robin 方式进行连续空间分配，导致磁盘碎片随时间累积。</p><p>优化内容包括：</p><ul><li><strong>碎片整理</strong>：重写对象以消除空间碎片</li><li><strong>重压缩（recompression）</strong>：对随机写入模式下压缩布局次优或未压缩的对象进行再压缩</li></ul><p>设计上引入了模块化插件机制（非真正的 plugin，而是一组优化组件），支持按优先级排序，由首个判断为有效的优化器执行并终止扫描流程。</p><h3 id="_2-log-like-对象的专用-api" tabindex="-1">2. Log-like 对象的专用 API <a class="header-anchor" href="#_2-log-like-对象的专用-api" aria-label="Permalink to &quot;2. Log-like 对象的专用 API&quot;">​</a></h3><p>针对 MDS journal、PG log 等具有顺序语义（非随机访问）的对象，在 object store 接口层新增专用 API。</p><p>现状问题：现有 object store API 以随机读写为主，对于只需 append（追加）和 trim（裁剪头部）的 log-like 对象而言效率较低。</p><p>方案设计：</p><ul><li>新增 <code>append</code>、<code>trim</code>、<code>sequential read</code> 方法</li><li>将此类对象内容直接存储在 BlueFS 中（类似 write-ahead log 的处理方式），绕过 RocksDB 元数据更新路径，缩短 IO 路径</li></ul><p>该特性仍处于方案设计和性能评估阶段。</p><h3 id="_3-机会性-discard-opportunistic-discards" tabindex="-1">3. 机会性 Discard（Opportunistic Discards） <a class="header-anchor" href="#_3-机会性-discard-opportunistic-discards" aria-label="Permalink to &quot;3. 机会性 Discard（Opportunistic Discards）&quot;">​</a></h3><p>解决大量数据删除（如移除整个 PG 或 pool）时空间无法及时回收的问题。</p><p>现有问题：启用 discard 后，释放的空间进入 discard 队列，在 discard 线程完成工作前，allocator 无法使用这部分空间，造成空间不可用的等待窗口。</p><p>新方案：</p><ul><li>立即将释放的空间归还给 allocator（逻辑上可分配），同时记录该区域待 discard 的信息</li><li>discard 线程在后台异步执行清理，不影响前台分配</li><li>额外收益：小对象覆写时旧空间可在下一次分配请求中直接复用，减少碎片</li><li>discard 线程积极程度可配置，无紧迫情况下可降低 discard 频率</li><li>两个块设备（main device 和 BlueFS）各自的 discard 线程将合并为一个，便于统一管控</li></ul><h3 id="_4-基于域的-allocator-domain-based-allocator" tabindex="-1">4. 基于域的 Allocator（Domain-Based Allocator） <a class="header-anchor" href="#_4-基于域的-allocator-domain-based-allocator" aria-label="Permalink to &quot;4. 基于域的 Allocator（Domain-Based Allocator）&quot;">​</a></h3><p>定位为碎片化问题的&quot;第二阶段&quot;解决方案（第一阶段为前述 scrub 优化 PR）。</p><p>核心思路：要求 BlueStore 各组件在申请 allocate 时附带数据类型信息，allocator 据此将数据分配到特定 bucket，使同类数据在磁盘上保持物理邻近。</p><p>已知不同数据类型具有差异显著的访问模式：</p><ul><li>BlueFS write-ahead log 与 BlueFS SST 文件</li><li>RBD 对象（高频覆写）</li><li>RGW 对象（写一次，保留至删除）</li></ul><p>额外收益：</p><ul><li>多 bucket 结构消除了对单一全局 mutex 的依赖，为更复杂的分配策略（可消耗更多 CPU 换取更好的对象局部性）创造条件</li><li>每个 bucket 可独立配置可用空间跟踪策略，未使用区域可不加载</li><li>未来可实现超大设备上 allocator 数据的动态加载与卸载</li></ul><h3 id="_5-本地元数据韧性-local-metadata-resiliency" tabindex="-1">5. 本地元数据韧性（Local Metadata Resiliency） <a class="header-anchor" href="#_5-本地元数据韧性-local-metadata-resiliency" aria-label="Permalink to &quot;5. 本地元数据韧性（Local Metadata Resiliency）&quot;">​</a></h3><p>背景：IBM 环境中开始使用非常大容量的 QLC 驱动器，预期数年使用后会出现性能退化和数据损坏风险。随着 OSD 容量增至多 TB 级别，完整的数据 backfill 恢复代价极高。</p><p>关注点：对象损坏可通过 Ceph 现有机制恢复，但 RocksDB 数据（write-ahead log 或 SST 文件）的损坏往往是致命的——OSD 可能无法启动，或即使通过 RocksDB repair 修复也不可信任。</p><p>三个目标应用场景：</p><ol><li>SMART 报告设备接近寿命末期，但运营方暂无资金更换，可牺牲性能换取更高数据韧性</li><li>超大容量磁盘场景，主动避免元数据损坏</li><li>使用已知故障率较高的廉价硬件时的成本优化部署</li></ol><p>该特性支持运行时动态启用（通过配置项），可在部署初期或 SMART 告警触发后按需开启。</p><h3 id="_6-pool-debug-模式-pool-debug-modes" tabindex="-1">6. Pool Debug 模式（Pool Debug Modes） <a class="header-anchor" href="#_6-pool-debug-模式-pool-debug-modes" aria-label="Permalink to &quot;6. Pool Debug 模式（Pool Debug Modes）&quot;">​</a></h3><p>面向开发者的调试工具，通过裁剪 BlueStore 标准处理流程，聚焦于 OSD messenger、PG lock 及网络层的性能测量。</p><p>提供多种 flag：</p><ul><li>对象读操作始终返回零</li><li>对象始终存在（跳过元数据读取）</li><li>跳过 IO</li><li>其他 flag 后续按需扩充</li></ul><h3 id="_7-bluestore-代码重构与模块化演进" tabindex="-1">7. BlueStore 代码重构与模块化演进 <a class="header-anchor" href="#_7-bluestore-代码重构与模块化演进" aria-label="Permalink to &quot;7. BlueStore 代码重构与模块化演进&quot;">​</a></h3><p>这是一项架构层面的长期规划，而非单一功能。</p><p>背景：BlueStore 当前实现已较为成熟，但代码耦合度高、模块化不足，引入新特性或重构现有功能的风险较大。</p><p>两阶段演进计划：</p><ol><li><strong>第一阶段</strong>：在保持现有功能不变的前提下，对代码进行模块化重构，引入可替换组件，支持通过配置项启用/禁用（类似现有多 allocator 实现的切换机制）</li><li><strong>第二阶段</strong>：在模块化基础上，为 BlueStore 建立 <strong>stable</strong> 和 <strong>experimental</strong> 两个配置集合，新特性先在 experimental 模式下经历 1-2 个版本的 baking 周期，充分验证后再纳入 stable</li></ol><p><strong>代码 reshuffle</strong>（已开始）：将 BlueStore 类中所有嵌套子类移出到独立 namespace，不修改任何逻辑，旨在解决 BlueStore 主类无限膨胀的问题，为后续重构奠定基础。</p><h2 id="社区互动" tabindex="-1">社区互动 <a class="header-anchor" href="#社区互动" aria-label="Permalink to &quot;社区互动&quot;">​</a></h2><ul><li>会后 Igor 提示，BlueStore 团队每周在相同时间段举办 <strong>BlueStore weekly call</strong>，链接已发布在 BlueStore Pad，欢迎社区成员参与</li><li>Anthony 呼吁更多社区成员参与 BlueStore 的贡献开发</li></ul><h2 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>状态</th></tr></thead><tbody><tr><td>Scrub-based space optimization PR</td><td>已在 review，关注 GitHub PR 进展</td></tr><tr><td>Log-like 对象 API 设计</td><td>方案评估中，需性能基准测试</td></tr><tr><td>Opportunistic discards</td><td>计划实现，初期版本为简单优先级调整</td></tr><tr><td>Domain-based allocator</td><td>设计阶段</td></tr><tr><td>Local metadata resiliency</td><td>评估是否实现</td></tr><tr><td>Pool debug modes</td><td>开发者工具，按需完善</td></tr><tr><td>代码 reshuffle</td><td>已启动</td></tr><tr><td>BlueStore 模块化重构</td><td>长期规划，依赖 reshuffle 完成后推进</td></tr></tbody></table>',48)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
